emit<Key extends keyof Events>(type: Key, evt?: Events[Key]) {
	let handlers = all!.get(type);
	if (handlers) {
		(handlers as EventHandlerList<Events[keyof Events]>)
			.slice()
			.map((handler) => {
				handler(evt!);
			});
	}

	handlers = all!.get('*');
	if (handlers) {
		(handlers as WildCardEventHandlerList<Events>)
			.slice()
			.map((handler) => {
				handler(type, evt!);
			});
	}
}

export interface Emitter<Events extends Record<EventType, unknown>> {
	all: EventHandlerMap<Events>;

	on<Key extends keyof Events>(type: Key, handler: Handler<Events[Key]>): void;
	on(type: '*', handler: WildcardHandler<Events>): void;

	off<Key extends keyof Events>(
		type: Key,
		handler?: Handler<Events[Key]>
	): void;
	off(type: '*', handler: WildcardHandler<Events>): void;

	emit<Key extends keyof Events>(type: Key, event: Events[Key]): void;
	emit<Key extends keyof Events>(
		type: undefined extends Events[Key] ? Key : never
	): void;
}

it('should invoke * handlers', () => {
	const star = spy(),
		ea = { a: 'a' },
		eb = { b: 'b' };

	events.set('*', [star]);

	inst.emit('foo', ea);
	expect(star).to.have.been.calledOnce.and.calledWith('foo', ea);
	star.resetHistory();

	inst.emit('bar', eb);
	expect(star).to.have.been.calledOnce.and.calledWith('bar', eb);
});

it('should invoke handler for type', () => {
	const event = { a: 'b' };

	inst.on('foo', (one, two?: unknown) => {
		expect(one).to.deep.equal(event);
		expect(two).to.be.an('undefined');
	});

	inst.emit('foo', event);
});

	// fooHandler is ok, because ('foo' | 'bar' | 'someEvent') extends string
	emitter.off('*', fooHandler);
	// @ts-expect-error
	emitter.off('*', barHandler);
}

/*
 * Check that 'emit' args are inferred correctly
 */
{
	// @ts-expect-error
	emitter.emit('someEvent', 'NOT VALID');
	emitter.emit('someEvent', { name: 'jack' });

	// @ts-expect-error
	emitter.emit('foo');
	// @ts-expect-error
	emitter.emit('foo', 1);
	emitter.emit('foo', 'string');

	emitter.emit('bar');
	emitter.emit('bar', 1);
	// @ts-expect-error
	emitter.emit('bar', 'string');
}

it('should NOT ignore case', () => {
	const onFoo = spy(),
		onFOO = spy();
	events.set('Foo', [onFoo]);
	events.set('FOO', [onFOO]);

	inst.emit('Foo', 'Foo arg');
	inst.emit('FOO', 'FOO arg');

	expect(onFoo).to.have.been.calledOnce.and.calledWith('Foo arg');
	expect(onFOO).to.have.been.calledOnce.and.calledWith('FOO arg');
});

export default function mitt<Events extends Record<EventType, unknown>>(
	all?: EventHandlerMap<Events>
): Emitter<Events> {

it('should be a function', () => {
	expect(inst).to.have.property('emit').that.is.a('function');
});

on<Key extends keyof Events>(type: Key, handler: GenericEventHandler) {
	const handlers: Array<GenericEventHandler> | undefined = all!.get(type);
	if (handlers) {
		handlers.push(handler);
	} else {
		all!.set(type, [handler] as EventHandlerList<Events[keyof Events]>);
	}
},

const emitter = mitt<{
	foo: string;
	someEvent: SomeEventData;
	bar?: number;
}>();

describe('mitt', () => {
	it('should default export be a function', () => {
		expect(mitt).to.be.a('function');
	});

	it('should accept an optional event handler map', () => {
		expect(() => mitt(new Map())).not.to.throw;
		const map = new Map();
		const a = spy();
		const b = spy();
		map.set('foo', [a, b]);
		const events = mitt<{ foo: undefined }>(map);
		events.emit('foo');
		expect(a).to.have.been.calledOnce;
		expect(b).to.have.been.calledOnce;
	});
});

### Typescript

Set `"strict": true` in your tsconfig.json to get improved type inference for `mitt` instance methods.

```ts
import mitt from 'mitt';

type Events = {
  foo: string;
  bar?: number;
};

const emitter = mitt<Events>(); // inferred as Emitter<Events>

emitter.on('foo', (e) => {}); // 'e' has inferred type 'string'

emitter.emit('foo', 42); // Error: Argument of type 'number' is not assignable to parameter of type 'string'. (2345)
```

Alternatively, you can use the provided `Emitter` type:

```ts
import mitt, { Emitter } from 'mitt';

type Events = {
  foo: string;
  bar?: number;
};

const emitter: Emitter<Events> = mitt<Events>();
```

